return {["fb39_01"]={["dsc"]=[[这里是封禅台左边的正气厅，原本是用作武林盟主赏善罚恶的大厅，现在已经被改造成皇帝封禅歇脚的地方。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb39_01]],["name"]=[[正气厅]],["permission"]=1,["right"]=[[fb39_02]],["stepMusic"]=[[jiaobu]]},["fb39_02"]={["dsc"]=[[这里是历代帝王封禅的场所，封禅台上摆放着祭祀用的器具，周围被重兵把守，无法靠近。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_02]],["item1"]=[[fb39item1]],["left"]=[[fb39_01]],["name"]=[[封禅台]],["permission"]=1,["right"]=[[fb39_03]],["stepMusic"]=[[jiaobu]]},["fb39_03"]={["down"]=[[fb39_07]],["dsc"]=[[这里是封禅台右边的侠义厅，与正气厅相对，来此修炼的侠客们经常在这里休息。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb39_03]],["item1"]=[[fb39item4]],["left"]=[[fb39_02]],["name"]=[[侠义厅]],["permission"]=1,["stepMusic"]=[[jiaobu]]},["fb39_04"]={["down"]=[[fb39_05]],["dsc"]=[[这里位于石马山的北麓，是岱顶的北面出口，路口有一石坊，上面写着「玄武」二字。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_04]],["item1"]=[[fb39item37]],["name"]=[[北天门]],["permission"]=2,["role1"]=[[fb39r04_1]],["stepMusic"]=[[jiaobu]]},["fb39_05"]={["dsc"]=[[这里位于玉皇顶以西里许的地方，形状有如一个伛偻的老人。附近有数块俊秀小石，故又有“老翁弄孙”之称。峰上有“天下第一山”、“凌霄峻极”、“中天独立”、“东柱第一灵区”诸刻，靠西有黄华洞，因洞路极为危险，后人在进路处写上「回车岩」。从这里往北走便是岱顶的北天门。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_05]],["name"]=[[丈人峰]],["permission"]=2,["rightDown"]=[[fb39_07]],["stepMusic"]=[[jiaobu]],["up"]=[[fb39_04]]},["fb39_06"]={["dsc"]=[[玉皇庙西厢就是望河亭。黄河金带为泰山六大奇观之一。若新霁无尘、夕阳西下时，举目北眺，在泰山西北层层峰峦的尽头，可看到黄河象一条金色的带子闪闪发光，或河水反射到天空，形成蜃景，波光粼粼，黄白相间，如同金银铺就一般，从西南至东北，一直伸向天地交界处。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_06]],["name"]=[[望河亭]],["permission"]=2,["right"]=[[fb39_07]],["role1"]=[[fb39r06_1]],["stepMusic"]=[[jiaobu]]},["fb39_07"]={["down"]=[[fb39_26]],["dsc"]=[[玉皇庙是处在泰山绝顶的庙观，古称太清宫、玉帝观，由山门、玉皇殿、观日亭、望河亭、东西道房组成。山门额书“敕修玉皇顶”。正殿内祀明代铜铸玉皇大帝像。神龛上匾额“柴望遗风”。远古帝王多在此燔柴祭天，望祀山川诸神。观前为古登封台，历代皇帝封禅的仪式都是在这里举行。]],["id"]=[[fb39_07]],["item1"]=[[fb39item5]],["left"]=[[fb39_06]],["leftUp"]=[[fb39_05]],["name"]=[[玉皇庙]],["permission"]=1,["right"]=[[fb39_08]],["rightDown"]=[[fb39_11]],["stepMusic"]=[[jiaobu]],["up"]=[[fb39_03]]},["fb39_08"]={["dsc"]=[[旭日东升是泰山最迷人的奇观。拂晓，天晴气朗，万壑收暝，东方一线晨曦由灰暗变淡黄，又由淡黄变成橘红。继而，云朵赤紫交杂，瞬息万变。满天彩霞与地平线上的茫茫雾气连为一体，云霞雾霭相映。赤轮乍启，海面半吞半吐，欲上而止，跳荡恍惚，仿佛有二日捧出。待日轮掀开云幕，冉冉升起，宛若飘荡着的宫灯。顷刻间，金光四射，群峰尽染。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_08]],["left"]=[[fb39_07]],["name"]=[[观日亭]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb39_09"]={["dsc"]=[[日观峰北有一块从山崖向横突出的巨石，名拱北石，又名探海石。长约二丈余，向东直指渤海。巨石三面无所凭依，视野广阔，但除非有绝高胆色的人，普通人一般都不敢攀登这块探海石。石上有“绝妙”、“船石岩”、“醉石”及明人题名等刻。登临其上可尽赏旭日东升的壮丽场面，亦可晴览山色、阴观云海。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_09]],["leftDown"]=[[fb39_11]],["name"]=[[探海石]],["permission"]=2,["role1"]=[[fb39r09_1]],["stepMusic"]=[[jiaobu]]},["fb39_10"]={["down"]=[[fb39_13]],["dsc"]=[[这里是东灵殿的后殿，道士们居住的场所。院子中间有两棵树，两棵树之间牵着绳子，挂满了晾晒的道士服。不远处传来饭香。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_10]],["item1"]=[[fb39item75]],["name"]=[[东灵后殿]],["permission"]=2,["role1"]=[[fb39r19_4]],["stepMusic"]=[[jiaobu]]},["fb39_11"]={["down"]=[[fb39_16]],["dsc"]=[[日观峰位于玉皇顶东南，古称介丘岩，因可观日出而名。相传在峰巅西可望秦，南可望越，故又称秦观峰、越观峰。这里怪石攒簇，最高的地方一石卓立，名为君子峰。往东走便是通往泰山东天门的山路。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_11]],["leftUp"]=[[fb39_07]],["name"]=[[日观峰]],["permission"]=2,["right"]=[[fb39_12]],["rightUp"]=[[fb39_09]],["role1"]=[[fb39r11_1]],["stepMusic"]=[[jiaobu]]},["fb39_12"]={["dsc"]=[[这里是日观峰小路，自峰顶东下，联结东天门。此处山势陡峭，两边下临深谷，一不小心都会掉了下去。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_12]],["left"]=[[fb39_11]],["name"]=[[日观山路]],["permission"]=2,["right"]=[[fb39_13]],["stepMusic"]=[[jiaobu]]},["fb39_13"]={["dsc"]=[[这里是一座道观。殿内布置肃穆，香炉里插着三柱清香，香烟袅袅上升，散发着一股檀香味。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb39_13]],["left"]=[[fb39_12]],["name"]=[[东灵殿]],["permission"]=2,["right"]=[[fb39_14]],["role1"]=[[fb39r13_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb39_10]]},["fb39_14"]={["dsc"]=[[这里是日观峰小路，自峰顶东下，联结东天门。此处山势陡峭，两边下临深谷，一不小心就会掉了下去。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_14]],["item1"]=[[fb39item14]],["left"]=[[fb39_13]],["name"]=[[日观小路]],["permission"]=2,["right"]=[[fb39_15]],["role1"]=[[fb39r14_1]],["stepMusic"]=[[jiaobu]]},["fb39_15"]={["dsc"]=[[日观峰东边为东天门，双石如门，是岱顶的东面出口。往东为伏虎门，峡口陡险。下为鹰愁涧，水东北流，入洗鹤湾。涧东岸北崖古洞深敞，名清静石屋，此处川林僻旷，尘迹罕至，俗呼仙人场。其北为空明山，中穴通明，午时日光穿照。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_15]],["left"]=[[fb39_14]],["name"]=[[东天门]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb39_16"]={["dsc"]=[[位于日观峰南边，便是爱身崖。爱身崖原名舍身崖，它三面陡峭，下临深渊。旧时常有人为祛父母病灾，祈求神灵，跳崖献身。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_16]],["leftDown"]=[[fb39_18]],["name"]=[[爱身崖]],["permission"]=2,["right"]=[[fb39_17]],["role1"]=[[fb39r16_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb39_11]]},["fb39_17"]={["dsc"]=[[爱身崖上有巨石突兀，高约丈许，石旁大书“瞻鲁台”，俗称幡杆石。传孔子曾登此瞻鲁都曲阜。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_17]],["left"]=[[fb39_16]],["name"]=[[瞻鲁台]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb39_18"]={["down"]=[[fb39_21]],["dsc"]=[[仙人桥在爱身崖西侧。两崖对峙，下临深涧，中有三石衔接抵撑而成桥状。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_18]],["name"]=[[仙人桥]],["permission"]=2,["rightUp"]=[[fb39_16]],["role1"]=[[fb39r18_1]],["stepMusic"]=[[jiaobu]]},["fb39_19"]={["down"]=[[fb39_22]],["dsc"]=[[孔子庙位于孔子崖下。庙有山门、正殿、配殿，内奉孔子，配祀颜子、曾子、子思、孟子等。山门上有题联:“仰之弥高，钻之弥坚，可以语上也，出乎其类，拔乎其萃，宜若登天然。”]],["id"]=[[fb39_19]],["item1"]=[[fb39item3]],["item2"]=[[fb39item63]],["name"]=[[孔子庙]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb39_20"]={["down"]=[[fb39_25]],["dsc"]=[[月观峰山阴有两块巨石壁立如门，犹如给人斩削过似的，正是岱顶的西面出口，称西天门。明万历年间林古度在石门上题“西阙”。钟惺在《登泰山记》中颂道：“岱之为天门者三，西天门者石自门焉，真天门也。”]],["fightBackground"]=[[森林内]],["id"]=[[fb39_20]],["name"]=[[西天门]],["permission"]=2,["role1"]=[[fb39r20_1]],["stepMusic"]=[[jiaobu]]},["fb39_21"]={["dsc"]=[[仙人桥南是望海石，巨石坦豁如鸟伏卧，石侧各有一小水槽，每逢雨后，水顺槽而流，如鸟之两翼。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_21]],["name"]=[[望海石]],["permission"]=2,["role1"]=[[fb39r21_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb39_18]]},["fb39_22"]={["down"]=[[fb39_27]],["dsc"]=[[孔子崖位于天街东首路北山岗上。传孔子与颜子登泰山至此，孔子东南望，看见吴国都城门下的一匹白马，此处遂名孔子崖或称望吴峰。崖上有“泰山乔岳”、“高山仰止”诸刻。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_22]],["name"]=[[孔子崖]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb39_19]]},["fb39_23"]={["dsc"]=[[这是泰山的其中一座山峰，又名悬石峰。山的东面有一个虎头崖，其形状有如一头伏虎。南面有避风崖，崖上大大地刻着「振衣冈」三字。崖南隔涧为莲花峰，上题“海日石莲”。峰顶二石钩连于上，名试心石。旧传朝山者登之，心诚则不动，不诚则摇跌入崖底。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_23]],["leftDown"]=[[fb39_27]],["name"]=[[围屏山]],["permission"]=1,["right"]=[[fb39_24]],["role1"]=[[fb39r23_1]],["role2"]=[[fb39r23_2]],["role3"]=[[fb39r23_3]],["stepMusic"]=[[jiaobu]]},["fb39_24"]={["dsc"]=[[这是一座历史悠久而宏伟壮丽的祠院。祠院设有东西两殿，分别称为东西宝库，储存着进香客的捐施，两殿的屋瓦都是由铁铸成。从四方八面来泰山上香的男女，都是先到碧霞祠，然后才到其他的庙宇。从这里往东南走便可到达宝藏岭。]],["id"]=[[fb39_24]],["left"]=[[fb39_23]],["leftDown"]=[[fb39_30]],["name"]=[[碧霞祠]],["permission"]=2,["rightDown"]=[[fb39_31]],["stepMusic"]=[[jiaobu]]},["fb39_25"]={["dsc"]=[[月观峰是位于南天门西面的山岭，与日观峰东西对峙而名。此处怪石攒簇，最高的地方一石卓立，名为君子峰。古人言可在此望越国，故又称越观峰。天晴气朗时，夜晚可观济南府城万家灯火，俗称望府山。山顶有月观亭，往北走便是泰山的西天门。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_25]],["item1"]=[[fb39item24]],["item2"]=[[fb39item25]],["name"]=[[月观峰]],["permission"]=2,["right"]=[[fb39_26]],["role1"]=[[fb39r25_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb39_20]]},["fb39_26"]={["down"]=[[fb39_32]],["dsc"]=[[走完了十八盘，便到南天门。南天门又称“三天门”，门为城楼式建筑，门边有一副对联，上覆摩空阁，是泰山顶的入口处。从这里附视山下，群山如龟伏地，河流如蚓缠绕，天地空阔，无可名状。从这里往东北走就是天街，往西走便是月观峰，往北走则是到玉皇顶之路。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_26]],["left"]=[[fb39_25]],["name"]=[[南天门]],["permission"]=1,["right"]=[[fb39_27]],["role1"]=[[fb39r26_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb39_07]]},["fb39_27"]={["down"]=[[fb39_36]],["dsc"]=[[此地在南天门东北，这里有数十户小贩聚而成市。道路平整，殿宇毗连，似天上街市。天街坊东路北，为皇帝旧行宫。从这里往东南走便是莲花峰，东北是围屏山，西便回到南天门。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_27]],["item1"]=[[fb39item2]],["left"]=[[fb39_26]],["name"]=[[天街]],["permission"]=1,["rightDown"]=[[fb39_33]],["rightUp"]=[[fb39_23]],["stepMusic"]=[[jiaobu]],["up"]=[[fb39_22]]},["fb39_28"]={["down"]=[[fb39_33]],["dsc"]=[[这里便是莲花峰的峰顶，由两块巨石勾连在一起，据说如果你心存诚意，登上试心石时石块便不会动摇，反之则摇动不止。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_28]],["item1"]=[[fb39r28_5]],["name"]=[[试心石]],["permission"]=1,["role1"]=[[fb39r28_1]],["role2"]=[[fb39r28_2]],["role3"]=[[fb39r28_3]],["role4"]=[[fb39r28_4]],["stepMusic"]=[[jiaobu]]},["fb39_29"]={["dsc"]=[[玉女池侧有巨石高耸黝黑若鼎，人题之为天柱。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_29]],["name"]=[[斯碑崖]],["permission"]=2,["right"]=[[fb39_30]],["stepMusic"]=[[jiaobu]]},["fb39_30"]={["dsc"]=[[玉女池在碧霞祠西墙外，原为池，后来修成了井。玉女池内发现过玉女石像，易以玉像，建龛奉祭，封为“天仙玉女碧霞元君”。从此香火大盛。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_30]],["left"]=[[fb39_29]],["name"]=[[玉女池]],["permission"]=2,["rightUp"]=[[fb39_24]],["stepMusic"]=[[jiaobu]]},["fb39_31"]={["dsc"]=[[这里是泰山的又一个名胜。岭上有一座状似狮子的巨石，称为狮子崖。最出名的还是要数在东北面的东岳庙，也称上岳庙。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_31]],["item1"]=[[fb39item28]],["leftUp"]=[[fb39_24]],["name"]=[[宝藏岭]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb39_32"]={["down"]=[[fb39_34]],["dsc"]=[[你爬在紧十八盘上，抬头只能看到前面的人的鞋底，低头穿裆则只见到后面人的发顶。在这里每走十来步便要稍一休息。西崖上有巨岩悬空，侧影佛头侧枕，高鼻秃顶，慈颜微笑，名迎客佛。十八盘岩层陡立，在不足两里地内升高近一里。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_32]],["item1"]=[[fb39item6]],["name"]=[[紧十八盘]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb39_26]]},["fb39_33"]={["dsc"]=[[莲花峰其实是由五座山峰攒簇而成，状如莲花，因以为名。东面有危崖万仞，叫五花崖。登上莲花峰后，可看到在盘道中的游人如小蚁般往来穿梭，故此莲花峰又叫望人峰。往上走便是莲花峰的峰顶。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_33]],["leftUp"]=[[fb39_27]],["name"]=[[莲花峰]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb39_28]]},["fb39_34"]={["down"]=[[fb39_38]],["dsc"]=[[这里是十八盘的中间，从这里直上南天门的一段就是紧十八盘了。由此刻攀石而上，后面的人可以看到前面的人的鞋底，前面的人回头则可见到后面的人的发顶。在这里一般人每走十来步便要稍一休息。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_34]],["item1"]=[[fb39item27]],["name"]=[[升仙坊]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb39_32]]},["fb39_35"]={["dsc"]=[[白云洞，又名云窝，因地处悬崖，下有绝涧，危岩多窍、白云缭绕而名。洞内明人题“卧云”、“锁云”，洞南深谷峻削，名百丈崖。]],["id"]=[[fb39_35]],["item1"]=[[fb39item69]],["item2"]=[[fb39item70]],["item3"]=[[fb39item71]],["item4"]=[[bfitem1]],["name"]=[[白云洞]],["permission"]=2,["right"]=[[fb39_36]],["role1"]=[[fb39item65]],["role2"]=[[fb39item66]],["role3"]=[[fb39item67]],["role4"]=[[fb39item68]],["stepMusic"]=[[jiaobu]]},["fb39_36"]={["dsc"]=[[天街南为象山，俗称象鼻峰，山南崖奇石下垂似象鼻而名。峰西为白云洞，峰东有青云洞。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_36]],["left"]=[[fb39_35]],["name"]=[[象山]],["permission"]=2,["right"]=[[fb39_37]],["role1"]=[[fb39r36_1]],["role2"]=[[fb39r36_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb39_27]]},["fb39_37"]={["dsc"]=[[这里是青云洞。传阴雨天洞内生青烟，与白云洞之云相遇即雨遍天下。正所谓“触石而出，肤寸而合，不崇朝而遍雨乎天下者，唯泰山尔”。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_37]],["item1"]=[[fb39item62]],["left"]=[[fb39_36]],["name"]=[[青云洞]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb39_38"]={["down"]=[[fb39_39]],["dsc"]=[[你走在不紧不慢十八盘上，两腿发软，挥汗如雨。两边是光秃的岩壁，无处可以遮风避日。十八盘的两山崖壁如削，陡峭的盘路镶嵌其中，远远望去，恰似天门云梯。回头看看，人行如蚁，尽在脚下。上头离南天门还好远呢。泰山之雄伟，尽在十八盘，泰山之壮美，尽在攀登中！]],["fightBackground"]=[[森林内]],["id"]=[[fb39_38]],["item1"]=[[fb39item7]],["item2"]=[[fb39item60]],["name"]=[[十八盘]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb39_34]]},["fb39_39"]={["down"]=[[fb39_40]],["dsc"]=[[此处山势陡峭，登山的人一个不小心很容易便会跌堕到崖谷之中。坊址东为大龙峪，雨季众水归峡，飞泉若泻。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_39]],["item1"]=[[fb39item8]],["item2"]=[[fb39item77]],["name"]=[[龙门]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb39_38]]},["fb39_40"]={["down"]=[[fb39_41]],["dsc"]=[[泰山有三个十八盘之说。自开山至龙门为“慢十八”，再至升仙坊为“不紧不慢又十八”，又至南天门为“紧十八”，共计一千六百三十余阶。你现在正走在慢十八盘上，低头就看见石阶。看着旁边挑担上山的挑夫，顿时自叹不如。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_40]],["name"]=[[慢十八盘]],["permission"]=2,["role1"]=[[fb39r40_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb39_39]]},["fb39_41"]={["down"]=[[fb39_42]],["dsc"]=[[对松山北，高阜之上，双崖夹道，旧称云门，今名开山。这里便是泰山十八盘的起点。此处向上，直到龙门，被称之为“慢十八盘”。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_41]],["name"]=[[开山]],["permission"]=2,["role1"]=[[fb39r41_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb39_40]]},["fb39_42"]={["down"]=[[fb39_43]],["dsc"]=[[出朝阳洞北去，便是对松山。对松山双峰对峙，古松万株，苍翠蓊郁，层层叠叠，又名万松山、松海。云出其间，天风莽荡，虬舞龙吟，松涛大作，堪称奇观…]],["fightBackground"]=[[森林内]],["id"]=[[fb39_42]],["name"]=[[对松山]],["permission"]=2,["role1"]=[[fb39r42_1]],["role2"]=[[fb39r42_2]],["role3"]=[[fb39r42_3]],["role4"]=[[fb39r42_4]],["stepMusic"]=[[jiaobu]],["up"]=[[fb39_41]]},["fb39_43"]={["dsc"]=[[这里是一个天然石穴，稍加整修，便深广如屋，南辟向阳，旧名迎阳、云阳。洞后壁线刻元君像。洞北有元君殿。洞东南翠峰崛起，虬松附石。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_43]],["name"]=[[朝阳洞]],["permission"]=2,["rightDown"]=[[fb39_44]],["stepMusic"]=[[jiaobu]],["up"]=[[fb39_42]]},["fb39_44"]={["dsc"]=[[《史记》载，秦始皇封泰山时中途遇雨，避于此间大树下，因封树为“五大夫”。后讹为五株。后古松被雷雨所毁。重修时，补植五株松。古松拳曲古拙，苍劲葱郁，自古被誉为“秦松挺秀”，列为泰安八景之一。五大夫松西拦住山坡上有望人松，长枝下垂，似躬身招手邀客，又名迎客松。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_44]],["leftUp"]=[[fb39_43]],["name"]=[[五大夫松]],["permission"]=2,["right"]=[[fb39_45]],["role1"]=[[fb39r44_1]],["stepMusic"]=[[jiaobu]]},["fb39_45"]={["dsc"]=[[沿阶而上，来到三磴崖，上有巨石如屋，此处曾遇暴风雨，石自山巅坠此，人称“飞来石”。御帐坪东有望驾石，如老翁拱立。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_45]],["left"]=[[fb39_44]],["name"]=[[三磴崖]],["permission"]=2,["right"]=[[fb39_46]],["stepMusic"]=[[jiaobu]]},["fb39_46"]={["down"]=[[fb39_48]],["dsc"]=[[在快活三里北首就是云步桥。因谷深林茂，常有云雾萦绕。桥北大壑忽临断崖，壁立如削。岱顶下诸水奔流而来，飞瀑下泻，溅沫迸珠，生云化雾，蔚为壮观，故又名飞瀑岩、天河、护驾泉。崖上有“红桥飞瀑”、“霖雨苍生”、“河山元脉”、“太古清音”等题刻。苍水佩悬云片片，珠帘洞织月娟娟。晚山倒着肩舆下，回看斜阳景更艳。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_46]],["left"]=[[fb39_45]],["name"]=[[云步桥]],["permission"]=2,["right"]=[[fb39_47]],["role1"]=[[fb39r46_1]],["stepMusic"]=[[jiaobu]]},["fb39_47"]={["dsc"]=[[云步桥东酌泉亭，又名观瀑亭。北侧有联:“且依石栏观飞瀑，再渡云桥访爵松。”云步桥周围有“月色泉声”、“云步跻天”、“耸壑昂霄”、“气象岩岩”等题刻五十余处，真、草、隶、篆，诸体荟萃，琳琅满目。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_47]],["item1"]=[[fb39item22]],["left"]=[[fb39_46]],["name"]=[[酌泉亭]],["permission"]=2,["role1"]=[[fb39r47_1]],["role2"]=[[fb39r47_2]],["stepMusic"]=[[jiaobu]]},["fb39_48"]={["down"]=[[fb39_49]],["dsc"]=[[快活三里在中天门北，又名快活山。登山至此，忽逢坦途，青山四围，下临绝涧，气爽景幽。南侧有名泉，武中奇题“玉液泉”，水甚甘冽。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_48]],["item1"]=[[fb39item59]],["name"]=[[快活三]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb39_46]]},["fb39_49"]={["down"]=[[fb39_50]],["dsc"]=[[这里又叫「中天门」。中天门峻岭阔谷，楼阁簇拥。东有中溪山突兀俏丽，可观日出，望晚霞，西有凤凰岭蜿蜓伸展，可远眺傲徕雄姿，俯视山下城廓。伫立坊下，北瞻巍巍岱峰，众山拱立，林茂泉飞，缆车凌空，天然成画。一般的登山者来到这里都已累极，但是这里才是泰山的一半啊！面对前面险峻的十八盘，很多人都不禁犹豫起来。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_49]],["name"]=[[二天门]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb39_48]]},["fb39_50"]={["dsc"]=[[回马岭古名石关，又名天关、瑞仙岩。此地山势陡峭，峰回路转，马至此不能登，故名。据说当年古代帝王上泰山封禅，来到这里，因陡峭难攀，累死了白马，要改乘小轿上山。石坊后盘路岌岌陡绝，东南上而西北折，形似马蹄，故称马蹄盘。崖壁题“勒马回看岱岭云”。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_50]],["name"]=[[回马岭]],["permission"]=2,["right"]=[[fb39_51]],["role1"]=[[fb39r50_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb39_49]]},["fb39_51"]={["down"]=[[fb39_52]],["dsc"]=[[壶天阁名取自道家以壶天为仙境之意。阁为跨道门楼式建筑，崔映辰题联：“壶天日月开灵境，盘路风云入翠微。”廷璐又联：“登此山一半已是壶天，造极顶千重尚多福地。”门洞有双柏自墙中横生，盘旋而上，堪称奇景。]],["id"]=[[fb39_51]],["left"]=[[fb39_50]],["name"]=[[壶天阁]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb39_52"]={["down"]=[[fb39_53]],["dsc"]=[[柏洞北面出去，有古槐株，高大擎云，蔚然葱翠，传为唐槐，其地名就叫四槐树。后来光阴荏苒，日月穿梭，又衍生了三株槐树，地名便不再改。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_52]],["item1"]=[[fb39item16]],["item2"]=[[fb39item55]],["item3"]=[[fb39item56]],["name"]=[[四槐树]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb39_51]]},["fb39_53"]={["down"]=[[fb39_54]],["dsc"]=[[你走到这里，但见古柏夹道，浓郁遮天，人行其中如入洞穴，虽炎夏酷暑而凉气宜人，暑气顿消。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_53]],["name"]=[[柏洞]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb39_52]]},["fb39_54"]={["down"]=[[fb39_55]],["dsc"]=[[登仙桥，俗称东西桥子，就在天绅岩北。桥西南遍地红沙石，名红沙岭。桥北东侧有古洞如棚，可以容马，被称为歇马崖。旧传吕洞宾曾在此崖上留墨。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_54]],["name"]=[[登仙桥]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb39_53]]},["fb39_55"]={["down"]=[[fb39_57]],["dsc"]=[[斗母宫北行不远，渐入空山，山路越来越不好走了。忽见前有石桥横跨，名注水流桥。桥西北危崖耸立，飞瀑散珠，如带若帘，名天绅岩，俗称水帘洞，锐锋丛生，景观独特。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_55]],["item1"]=[[fb39item18]],["item2"]=[[fb39item54]],["name"]=[[天绅台]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb39_54]]},["fb39_56"]={["dsc"]=[[经刻西北有巨石，高约两丈，宽近五丈，石辟为两半，上题“试剑石”三字，又名仙峡石。柱联:“天门倒泻一帘雨，梵石灵呵千载文。”崖摩刻《高山流水亭记》。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_56]],["item1"]=[[fb39item53]],["leftDown"]=[[fb39_58]],["name"]=[[试剑石]],["permission"]=2,["role1"]=[[fb39r56_1]],["stepMusic"]=[[jiaobu]]},["fb39_57"]={["down"]=[[fb39_60]],["dsc"]=[[斗母宫为泰山古道观。宫东临龙泉峰，又有龙泉水自西北山峡绕宫东注中溪，故又名龙泉观。宫筑于盘道旁深壑绝壁之上，深秀幽雅。早年尼姑住持，祀北斗众星之母，遂更名斗姥宫，又名妙香院，俗称斗母宫。正殿原祀斗母神，俗称千手千眼佛。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_57]],["leftDown"]=[[fb39_59]],["name"]=[[斗母宫]],["permission"]=2,["right"]=[[fb39_58]],["rightDown"]=[[fb39_61]],["stepMusic"]=[[jiaobu]],["up"]=[[fb39_55]]},["fb39_58"]={["dsc"]=[[这里是一块大石坪，石面刻有篆文「金刚经」，字体其大如斗，但却没有记载刻石者的名字和刻石的年代。经石峪四面环山，深谷幽奥。龙泉峰耸峙于东，锐若茁笋，炮高岭横亘于西，涧水自东北三叉沟乱石中泠泠而出，绕龙泉峰流入中溪。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_58]],["item1"]=[[fb39item52]],["left"]=[[fb39_57]],["name"]=[[经石峪]],["permission"]=2,["rightUp"]=[[fb39_56]],["stepMusic"]=[[jiaobu]]},["fb39_59"]={["dsc"]=[[斗母宫南西崖有“蔚然深秀”、“洞天福地”、“肤寸升云”及“虫二”诸刻，与山色辉映。“虫二”字谜即“风月”二字拆去边框，意为风月无边，景色秀丽。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_59]],["name"]=[[风月无边]],["permission"]=2,["rightUp"]=[[fb39_57]],["role1"]=[[2019qxcdg1a]],["role2"]=[[2019qxcdg1b]],["stepMusic"]=[[jiaobu]]},["fb39_60"]={["down"]=[[fb39_62]],["dsc"]=[[桃花涧，又名樱桃园，涧中石坪广阔，断崖跌宕，溪水潺潺而来，滢洄湍急而去，或为瀑，或为潭，或潜流，汇为深广碧池，名碧泉湾。今涧内桃、樱均无，唯杨、槐满谷，柏林夹岸，石峡飞流，瀑水如帘。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_60]],["name"]=[[桃花涧]],["permission"]=2,["role1"]=[[fb39r60_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb39_57]]},["fb39_61"]={["dsc"]=[[斗母宫东有听泉山房及龙泉亭，供游人小憩赏景。亭下涧内“三潭叠瀑”如龙飞舞，名飞龙涧。游人立于潭间，流水声似丝竹奏鸣。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_61]],["leftUp"]=[[fb39_57]],["name"]=[[飞龙涧]],["permission"]=2,["role1"]=[[fb39r61_1]],["stepMusic"]=[[jiaobu]]},["fb39_62"]={["down"]=[[fb39_63]],["dsc"]=[[万仙楼为跨道门楼式建筑。殿内祀王母，配以列仙，后增祀元君。殿墙四周镶明代朝山进香碑六十三块。门洞东侧有隐真洞，为旧时道人修炼处。门洞后额书“谢恩处”，传古帝王登山时，地方官员送驾至此而谢归。或称旧时香客登岱回归至此无恙，即叩谢元君保佑之恩。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_62]],["item1"]=[[fb39item51]],["name"]=[[万仙楼]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb39_60]]},["fb39_63"]={["down"]=[[fb39_64]],["dsc"]=[[万仙楼位于红门宫北，楼前有古柏三株，挺拔并列，苍翠凌云，碣书“三义柏”。再前西崖题“勇登仙境”，下有洞，洞内有石龟，俗称龟洞。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_63]],["item1"]=[[fb39item48]],["item2"]=[[fb39item49]],["item3"]=[[fb39item50]],["name"]=[[三义柏]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb39_62]]},["fb39_64"]={["down"]=[[fb39_67]],["dsc"]=[[从岱宗坊上山大约走四里，便来到一天门。北面有一座天阶坊，过了此坊便进入了登泰山的盘道。南面有一座更衣亭，士大夫们及其随从，都会在这里换上轻便的服装，才继续登山。从一天门向北眺望，南天门与十八盘在云雾明灭间或隐或现，登泰山的人到此已有观止之叹。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_64]],["leftDown"]=[[fb39_66]],["name"]=[[一天门]],["permission"]=2,["role1"]=[[fb39r64_1]],["role2"]=[[fb39r64_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb39_63]]},["fb39_65"]={["dsc"]=[[红门宫东北深涧内，就是小洞天。这里片石如几，厚五尺，方圆丈许。此处一壑曲绕，清溪碧潭，山林涧草，森森蔓蔓，别有洞天。谷底断崖层叠，横瀑飞流，自北而南有柳条、饮马、石峡三湾。谷侧多圆柱形铁黑色巨石，横断面层层包裹，似枯木年轮，上刻“醉心”。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_65]],["item1"]=[[fb39item20]],["leftDown"]=[[fb39_67]],["name"]=[[小洞天]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb39_66"]={["dsc"]=[[一天门坊前路西是关帝庙，祀三国时蜀汉名将关羽。山西盐商常在此聚会祭祀，奉福神，故又名山西会馆。庙东院有古柏一株，墙外碣书“汉柏第一”。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_66]],["item1"]=[[fb39item47]],["name"]=[[关帝庙]],["permission"]=2,["rightUp"]=[[fb39_64]],["role1"]=[[fb39r66_1]],["role2"]=[[fb39r66_2]],["stepMusic"]=[[jiaobu]]},["fb39_67"]={["down"]=[[fb39_69]],["dsc"]=[[红门宫东临中溪，西靠大藏岭，是泰山中溪的门户，呈半封闭凹形空间。再加宫前三重白色石坊及碑碣，构成一组高低错落、色彩鲜明、形若天梯的古建筑群。自飞云阁洞北望，林荫夹道，石级绵延。自古有“红门晓日”之景。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_67]],["name"]=[[红门宫]],["permission"]=2,["right"]=[[fb39_68]],["rightUp"]=[[fb39_65]],["stepMusic"]=[[jiaobu]],["up"]=[[fb39_64]]},["fb39_68"]={["dsc"]=[[弥勒院由祀观音大士之飞云阁与红门宫相连。东院正殿原祀木雕弥勒佛，东有穿堂式更衣亭，旧时帝王官宦登山至此更衣，南有穿堂式过庭。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_68]],["left"]=[[fb39_67]],["name"]=[[弥勒院]],["permission"]=2,["rightDown"]=[[fb39_70]],["role1"]=[[fb39r68_1]],["stepMusic"]=[[jiaobu]]},["fb39_69"]={["down"]=[[fb39_71]],["dsc"]=[[相传从前这里有一个白鹤泉，它的水清凉甘甜，为泰山之最。这泉水长年涌流不断，喷出的水象仙鹤扑扇着翅膀洗澡一样，因以为名。可惜后来有一个自私自利的小官，独霸了泉水，后来更因迷信风水之说，把泉眼堵塞，白鹤泉从此便干涸了。现在只剩下一座刻着「白鹤泉」三字的石坊以为纪念。从这里继续北上，便是上山之路。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_69]],["item1"]=[[fb39item46]],["name"]=[[白鹤泉]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb39_67]]},["fb39_70"]={["dsc"]=[[红门宫东出跨溪而南是白骡冢。传古代帝王登泰山时乘白骡，礼毕下山至此，骡累死，遂封“白骡将军”，并备棺垒石为冢。现冢无存，仅留石碑，传为白骡冢碑。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_70]],["item1"]=[[fb39item38]],["item2"]=[[fb39item39]],["item3"]=[[fb39item40]],["leftUp"]=[[fb39_68]],["name"]=[[白骡冢]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb39_71"]={["down"]=[[fb39_72]],["dsc"]=[[岱宗坊，坊建于台基上，四柱三门式，相传当年碧霞元君被姜子牙戏弄，诱她投掷绣花鞋以定泰山地界，结果碧霞元君只能把绣花鞋从山顶掷到此处。从此泰山便以此为起点。坊东丰都庙，祀丰都大帝，配以冥府十王。坊北三皇庙，祀伏羲、神农、黄帝，配以八蜡神。坊西建封院，宋政和年间改为升元观，祀东岳福神东华帝君。坊内松柏郁郁，奇石林立，溪泉争流。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_71]],["name"]=[[岱宗坊]],["permission"]=2,["role1"]=[[fb39r71_1]],["role2"]=[[fb39r71_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb39_69]]},["fb39_72"]={["down"]=[[fb39_73]],["dsc"]=[[泰山脚下岱庙，是东岳福神东华帝君的道场。从南到北依次贯穿正阳门、配天门、仁安门、天贶殿、后寝宫、厚载门，东侧辅以汉柏院、东御座，西侧佐以唐槐院、雨花道院，极其宏大壮丽，东岳大帝的灵感可见。往北就是岱宗坊。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_72]],["name"]=[[岱庙]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb39_71]]},["fb39_73"]={["down"]=[[fb39_74]],["dsc"]=[[这里为岱庙前庭，旧称草参门、草参亭。古人凡有事于泰山，必先至此进行简单参拜，而后入庙祭神。亭为二进院落。前院正殿祀碧霞元君，两侧为东西配殿两侧铁狮对峙，旗杆高竖。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_73]],["item1"]=[[fb39item45]],["name"]=[[遥参亭]],["permission"]=2,["role1"]=[[fb39r73_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb39_72]]},["fb39_74"]={["dsc"]=[[泰山古称岱山，为五岳的东岳，为道教第二小洞天，向有“五岳独尊”之称誉，以“泰山天下雄”名闻域内。往北就到进入岱宗坊的前庭遥参亭了。]],["fightBackground"]=[[森林内]],["id"]=[[fb39_74]],["item1"]=[[fb39item78]],["name"]=[[泰山脚下]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb39_73]]}}00000000